export function getFragmentWays(config: AppConfig): FragmentWay[] {
  const enabledWheelRewards = config.wheelRewards.filter((reward) => reward.enabled !== false);
  const configuredAchievements = config.customAchievements.filter((achievement) => achievement.enabled).length;
  return fragmentWays.map((way) => {
    if (way.title === "Vòng quay phần thưởng") {
      return { ...way, status: enabledWheelRewards.length ? "active" : "planned", milestone: enabledWheelRewards.length ? `${enabledWheelRewards.length} phần thưởng đang bật; vé quay và điều kiện nhận được áp dụng theo cấu hình.` : "Chưa có phần thưởng đang bật; Admin/Founder cần cấu hình trước khi mở.", label: enabledWheelRewards.length ? "Mở Vòng quay" : "Chờ cấu hình" };
    }
    if (way.title === "Thành tích đặc biệt") {
      return { ...way, status: configuredAchievements ? "configured" : "planned", milestone: configuredAchievements ? `${configuredAchievements} mốc thành tích đang được theo dõi theo tiến trình hồ sơ.` : "Chưa có mốc thành tích; Admin/Founder cần cấu hình trước.", label: configuredAchievements ? "Xem Thành tích" : "Chờ cấu hình" };
    }
    return way;
  });
}

