function AchievementMuseum({ profile, config }: { profile: ProfileState; config: AppConfig }) {
  const achievements = allAchievementsWithProgress(profile, config);
  const unlocked = achievements.filter((item) => Boolean(item.unlockedAt));
  const grouped = unlocked.reduce<Record<string, typeof unlocked>>((result, item) => {
    const date = item.unlockedAt ? new Date(item.unlockedAt) : new Date();
    const year = String(date.getFullYear());
    const month = date.toLocaleDateString("vi-VN", { month: "long" });
    const key = `${year} · ${month}`;
    (result[key] ??= []).push(item);
    return result;
  }, {});
  const groups = Object.entries(grouped);
  return <section className="panel mt-7 overflow-hidden p-6" aria-labelledby="achievement-museum-title">
    <div className="flex flex-wrap items-start justify-between gap-4">
      <div>
        <p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Bảo tàng hiện vật học tập</p>
        <h2 id="achievement-museum-title" className="mt-2 font-display text-2xl font-bold">🏛️ Bảo tàng Hành trình</h2>
        <p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Mỗi thành tích đã mở khóa là một hiện vật của riêng Ong. Nhấn vào từng hiện vật để đọc lại câu chuyện, lý do và bước tiến đã tạo nên nó.</p>
      </div>
      <div className="flex items-center gap-3 rounded-2xl border border-green-200 bg-green-50 px-4 py-3 text-right dark:border-green-400/20 dark:bg-green-500/[.08]">
        <OngLearnerAvatar variant="hoodie" size="sm" />
        <div>
          <p className="text-2xl font-black text-green-800 dark:text-green-200">🌱 {unlocked.length}/{achievements.length}</p>
          <p className="mt-1 max-w-44 text-xs font-bold leading-5 text-green-800 dark:text-green-200">Ong đã mở khóa {unlocked.length} dấu mốc trong hành trình của mình.</p>
        </div>
      </div>
    </div>
    {groups.length === 0 ? <div className="mt-6 rounded-3xl border border-dashed border-amber-300 bg-amber-50/60 p-6 text-center dark:border-amber-400/20 dark:bg-amber-500/[.05]"><p className="text-3xl">🌱</p><p className="mt-2 font-display text-lg font-bold">Hiện vật đầu tiên đang chờ Ong tạo ra</p><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-slate-500">Không cần mở khóa thật nhiều. Một lần bắt đầu, một lỗi được sửa, hay một phiên học ngắn đều có thể trở thành trang đầu tiên của Bảo tàng.</p></div> : <div className="mt-6 space-y-5">{groups.map(([period, items]) => <section key={period} aria-label={`Hiện vật ${period}`} className="rounded-3xl border border-amber-100 bg-amber-50/45 p-4 dark:border-amber-400/15 dark:bg-amber-500/[.04]"><div className="flex items-center gap-3"><span className="text-2xl" aria-hidden="true">{period.includes("tháng 8") ? "🔥" : "🌱"}</span><div><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-700 dark:text-amber-300">Mốc thời gian</p><h3 className="font-display text-lg font-bold capitalize">{period}</h3></div><span className="ml-auto rounded-full bg-white/80 px-3 py-1 text-xs font-bold text-amber-800 dark:bg-white/10 dark:text-amber-200">{items.length} hiện vật</span></div><div className="mt-4 grid gap-3 md:grid-cols-2">{items.map((item) => <details key={item.id} className="group rounded-2xl border border-white/80 bg-white/80 p-4 shadow-sm dark:border-white/10 dark:bg-white/[.04]"><summary className="cursor-pointer list-none"><div className="flex items-start gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-green-100 text-lg dark:bg-green-500/15">🏅</span><div className="min-w-0"><p className="font-bold text-slate-900 dark:text-white">{item.name}</p><p className="mt-1 text-xs text-slate-500">Đã mở khóa · {item.unlockedAt ? new Date(item.unlockedAt).toLocaleDateString("vi-VN") : "trong hành trình"}</p></div><span className="ml-auto text-xs text-green-700 transition-transform group-open:rotate-180 dark:text-green-300">⌄</span></div></summary><div className="mt-3 border-t border-green-100 pt-3 text-sm leading-6 dark:border-green-400/15"><p className="text-slate-600 dark:text-slate-300">{item.description}</p><p className="mt-2 font-bold text-green-700 dark:text-green-300">Câu chuyện của hiện vật</p><p className="mt-1 text-slate-600 dark:text-slate-300">{getAchievementStory(item.name, item.description, true)}</p><p className="mt-2 text-xs font-bold text-amber-700 dark:text-amber-300">🔎 {achievementEvidenceFor(profile, item).map((evidence) => `${evidence.label}: ${evidence.value}`).join(" · ")}</p></div></details>)}</div></section>)}</div>}
  </section>;
}

function ProgressTree({ profile, config }: { profile: ProfileState; config: AppConfig }) {
  const achievements = allAchievementsWithProgress(profile, config).slice(0, 12);
  const branches = ["Tập trung", "Hiểu sâu", "Bền bỉ"];
  return <section className="panel mt-7 p-6" aria-labelledby="progress-tree-title"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-green-700 dark:text-green-300">Cây kỹ năng</p><h2 id="progress-tree-title" className="mt-2 font-display text-2xl font-bold">🌳 Cây tiến bộ</h2></div><OngLearnerAvatar variant="hoodie" size="sm" /></div><div className="mt-6 grid gap-4 md:grid-cols-3">{branches.map((branch, branchIndex) => <div key={branch} className="rounded-3xl border border-green-100 bg-green-50/70 p-4 dark:border-green-400/15 dark:bg-green-500/[.05]"><div className="text-center text-3xl">{branchIndex === 0 ? "🍅" : branchIndex === 1 ? "🧠" : "🔥"}</div><h3 className="mt-2 text-center font-display font-bold">{branch}</h3><div className="mt-4 space-y-3">{achievements.slice(branchIndex * 4, branchIndex * 4 + 4).map((item, index) => <div key={item.id} className="relative rounded-2xl border border-white/80 bg-white/80 p-3 dark:border-white/10 dark:bg-white/[.04]"><span className="absolute -left-2 top-3 h-4 w-4 rounded-full border-4 border-green-100 bg-green-600 dark:border-green-950" /><p className="pl-3 text-sm font-bold">{item.unlockedAt ? item.name : "Chưa mở nút này"}</p><p className="pl-3 text-xs text-slate-500">{item.unlockedAt ? `Đã mở · ${item.progress}%` : "Tiếp tục học để khám phá"}</p>{index < 3 && <div className="absolute -bottom-4 left-0 h-4 border-l border-dashed border-green-400" />}</div>)}</div></div>)}</div><p className="mt-5 text-xs text-slate-500">Mỗi node là một dấu mốc riêng; cây chỉ ghi nhận tiến trình, không trừ XP khi Ong nghỉ.</p></section>;
}

function AchievementMoments({ profile, config, onProfile }: { profile: ProfileState; config: AppConfig; onProfile: (profile: ProfileState, message?: string) => void }) {
  const [note, setNote] = useState("");
  const [feeling, setFeeling] = useState("Tự hào");
  const unlocked = allAchievementsWithProgress(profile, config).filter((item) => item.unlockedAt).slice(0, 6);
  const allMoments = profile.achievementMoments ?? [];
  const moments = allMoments.filter((moment) => !moment.deletedAt);
  const deletedMoments = allMoments.filter((moment) => Boolean(moment.deletedAt));
  const [photoUrl, setPhotoUrl] = useState("");
  const saveMoment = (achievementId: string) => { const moment: AchievementMoment = { id: `moment-${Date.now()}`, achievementId, createdAt: new Date().toISOString(), note: note.trim(), feeling, mascotVariant: "hoodie", ...(photoUrl.trim() ? { photoUrl: photoUrl.trim() } : {}) }; onProfile({ ...profile, achievementMoments: [...allMoments, moment] }, "Đã lưu Khoảnh khắc mở khóa với Ong hoodie."); setNote(""); setPhotoUrl(""); };
  const updateMoment = (id: string, patch: Partial<AchievementMoment>, message: string) => onProfile({ ...profile, achievementMoments: allMoments.map((moment) => moment.id === id ? { ...moment, ...patch } : moment) }, message);
  const moveMomentToTrash = (id: string) => updateMoment(id, { deletedAt: new Date().toISOString() }, "Đã chuyển Khoảnh khắc vào thùng rác.");
  const restoreMoment = (id: string) => updateMoment(id, { deletedAt: undefined }, "Đã khôi phục Khoảnh khắc.");
  const permanentlyDeleteMoment = (id: string) => { if (!window.confirm("Xóa vĩnh viễn Khoảnh khắc này? Thao tác không thể hoàn tác.")) return; onProfile({ ...profile, achievementMoments: allMoments.filter((moment) => moment.id !== id) }, "Đã xóa vĩnh viễn Khoảnh khắc."); };
  return <section className="panel mt-7 p-6" aria-labelledby="moments-title"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-red-700 dark:text-red-300">Lưu dấu hành trình</p><h2 id="moments-title" className="mt-2 font-display text-2xl font-bold">📸 Khoảnh khắc khi đạt</h2></div><OngLearnerAvatar variant="hoodie" size="sm" /></div><p className="mt-2 text-sm leading-6 text-slate-500">Chỉ tạo khoảnh khắc cho achievement đã mở khóa; không bịa ảnh hay tiến độ. Bạn có thể ghi chú và cảm xúc, mascot mặc hoodie được gắn cố định.</p><div className="mt-5 grid gap-4 lg:grid-cols-[1fr_1.2fr]"><div className="rounded-3xl border border-red-100 bg-red-50/60 p-4 dark:border-red-400/15 dark:bg-red-500/[.05]"><label className="text-sm font-bold" htmlFor="moment-note">Ghi vài dòng</label><textarea id="moment-note" className="input mt-2 min-h-24 w-full" value={note} onChange={(event) => setNote(event.target.value)} placeholder="Hôm nay Ong đã làm được gì?" /><label className="mt-3 block text-sm font-bold" htmlFor="moment-feeling">Cảm xúc</label><select id="moment-feeling" className="input mt-2 w-full" value={feeling} onChange={(event) => setFeeling(event.target.value)}><option>Tự hào</option><option>Nhẹ nhõm</option><option>Vui</option><option>Bình tĩnh</option></select><label className="mt-3 block text-sm font-bold" htmlFor="moment-photo">URL ảnh tùy chọn</label><input id="moment-photo" className="input mt-2 w-full" value={photoUrl} onChange={(event) => setPhotoUrl(event.target.value)} placeholder="https://... (không bắt buộc)" /><p className="mt-3 text-xs text-slate-500">Ảnh đại diện mặc định của khoảnh khắc: Ong hoodie. Chỉ lưu URL, không lưu bytes ảnh vào cloud-state.</p></div><div className="space-y-3">{unlocked.length === 0 ? <div className="rounded-3xl border border-dashed border-slate-300 p-5 text-sm text-slate-500">Chưa có achievement mở khóa để lưu khoảnh khắc. Khi có dữ liệu thật, Lumi sẽ mời Ong lưu lại.</div> : unlocked.map((item) => { const saved = moments.some((moment) => moment.achievementId === item.id); return <article key={item.id} className="rounded-3xl border border-green-100 bg-green-50/60 p-4 dark:border-green-400/15 dark:bg-green-500/[.05]"><div className="flex items-center gap-3"><OngLearnerAvatar variant="hoodie" size="sm" /><div><h3 className="font-bold">🏆 {item.name}</h3><p className="text-xs text-slate-500">Câu chuyện: {getAchievementStory(item.name, item.description, true)}</p>{saved && <p className="mt-1 text-xs text-green-700">Khoảnh khắc đang được lưu.</p>}</div></div><button className="primary-button mt-3 px-3 py-2 text-xs" disabled={saved} onClick={() => saveMoment(item.id)}>{saved ? "Đã lưu khoảnh khắc" : "Lưu khoảnh khắc này"}</button></article>; })}</div></div>{moments.length > 0 && <div className="mt-4 space-y-3"><p className="text-xs font-bold text-green-700 dark:text-green-300">Đã lưu {moments.length} khoảnh khắc thật trong hồ sơ.</p>{moments.map((moment) => <article key={moment.id} className="rounded-2xl border border-slate-200 bg-white/70 p-3 dark:border-white/10 dark:bg-white/[.04]"><div className="flex flex-wrap items-center gap-3"><OngLearnerAvatar variant="hoodie" size="sm" /><div className="min-w-0 flex-1"><p className="text-sm font-bold">{moment.feeling} · {new Date(moment.createdAt).toLocaleDateString()}</p><input aria-label={`Sửa ghi chú Khoảnh khắc ${moment.id}`} className="input mt-2 w-full" value={moment.note} onChange={(event) => updateMoment(moment.id, { note: event.target.value }, "Đã cập nhật ghi chú Khoảnh khắc.")} /></div><button className="secondary-button px-3 py-2 text-xs" onClick={() => moveMomentToTrash(moment.id)}>🗑️ Thùng rác</button></div></article>)}</div>}
        {deletedMoments.length > 0 && <div className="mt-5 rounded-2xl border border-dashed border-red-200 bg-red-50/60 p-4 dark:border-red-400/20 dark:bg-red-500/[.05]"><p className="text-sm font-bold text-red-800 dark:text-red-200">🗑️ Thùng rác Khoảnh khắc</p><div className="mt-3 space-y-2">{deletedMoments.map((moment) => <div key={moment.id} className="flex flex-wrap items-center gap-2 text-sm"><span className="min-w-0 flex-1 truncate">{moment.note || "Khoảnh khắc không có ghi chú"}</span><button className="secondary-button px-2 py-1 text-xs" onClick={() => restoreMoment(moment.id)}>Khôi phục</button><button className="secondary-button px-2 py-1 text-xs text-red-700" onClick={() => permanentlyDeleteMoment(moment.id)}>Xóa vĩnh viễn</button></div>)}</div></div>}</section>;
}

export default function MuseumJourney({ account, profile, config, onView, onProfile }: { account: StudyAccount; profile: ProfileState; config: AppConfig; onView: (view: LearningView) => void; onProfile: (profile: ProfileState, message?: string) => void }) {
  const [celebration, setCelebration] = useState<Celebration | null>(null);
  const [animationsEnabled, setAnimationsEnabled] = useState(true);
  const previousSnapshot = useRef<{ pieces: number; titleIds: string[] } | null>(null);
  const achievements = allAchievementsWithProgress(profile, config);
  useEffect(() => {
    try { setAnimationsEnabled(window.localStorage.getItem("study-empire-celebrations") !== "off"); } catch { /* localStorage có thể bị chặn */ }
  }, []);
  useEffect(() => {
    const pieces = Object.values(profile.fragments).reduce((sum, value) => sum + Math.max(0, value), 0);
    const titleIds = achievements.filter((item) => Boolean(item.title && item.unlockedAt)).map((item) => item.id);
    const previous = previousSnapshot.current;
    previousSnapshot.current = { pieces, titleIds };
    if (!previous) return;
    const newTitle = achievements.find((item) => Boolean(item.title && item.unlockedAt && !previous.titleIds.includes(item.id)));
    if (newTitle) {
      setCelebration({ kind: "title", icon: "🏅", title: `Danh hiệu mới: ${newTitle.title}`, detail: `Ong đã mở khóa “${newTitle.name}”. Hãy xem điều kiện, câu chuyện và ý nghĩa văn hóa của danh hiệu trong Bảo tàng Hành trình.` });
    } else if (pieces > previous.pieces) {
      setCelebration({ kind: "fragment", icon: "🧩", title: "Ong vừa thu thập mảnh ghép!", detail: `Kho của Ong tăng thêm ${pieces - previous.pieces} mảnh. Mảnh ghép được dùng để mở khóa và hoàn thiện hồ sơ nhân vật lịch sử, không phải để ghép tranh.` });
    }
  }, [profile, achievements]);
  useEffect(() => { if (!celebration) return; const timer = window.setTimeout(() => setCelebration(null), 5200); return () => window.clearTimeout(timer); }, [celebration]);
  const toggleAnimations = (enabled: boolean) => { setAnimationsEnabled(enabled); try { window.localStorage.setItem("study-empire-celebrations", enabled ? "on" : "off"); } catch { /* localStorage có thể bị chặn */ } };
  return <>
    <CelebrationOverlay celebration={celebration} enabled={animationsEnabled} onDismiss={() => setCelebration(null)} />
    <PersistentCollapsible storageKey="museum-enhanced" eyebrow="Bảo tàng hành trình" title="Tổng quan hành trình"><MuseumEnhanced account={account} profile={profile} config={config} /></PersistentCollapsible>
    <PersistentCollapsible storageKey="museum-collection-progress" eyebrow="Tiến độ sưu tập" title="Tiến độ Thành tích và Danh hiệu"><CollectionProgress profile={profile} config={config} animationsEnabled={animationsEnabled} onToggleAnimations={toggleAnimations} /></PersistentCollapsible>
    <PersistentCollapsible storageKey="museum-fragment-ways" eyebrow="Tiến trình phần thưởng" title="Cách nhận mảnh ghép"><section className="mt-0" aria-labelledby="fragment-ways-title"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">Tiến trình phần thưởng</p><h2 id="fragment-ways-title" className="mt-2 font-display text-2xl font-bold">🧩 Cách nhận mảnh ghép</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Mỗi mảnh ghép là một dấu vết đáng nhớ trên hành trình học của Ong. Không cần sưu tầm đủ mọi thứ; chỉ cần trân trọng những bước tiến mà Ong đã tạo ra.</p></div><span className="inline-flex items-center gap-2 rounded-full bg-amber-100 px-3 py-2 text-sm font-bold text-amber-900 dark:bg-amber-500/15 dark:text-amber-100"><Puzzle className="h-4 w-4" />{Object.values(profile.fragments).reduce((sum, value) => sum + Math.max(0, value), 0)} mảnh đang giữ</span></div><div className="mt-6 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{getFragmentWays(config).map((way) => <article key={way.title} className="rounded-2xl border border-amber-100 bg-white/70 p-4 dark:border-amber-400/15 dark:bg-white/[.035]"><div className="flex items-start gap-3"><span className="text-2xl" aria-hidden="true">{way.icon}</span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-display text-base font-bold">{way.title}</h3><span data-config-state={way.status} className={`rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${way.status === "active" ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-500/15 dark:text-emerald-200" : way.status === "configured" ? "bg-amber-100 text-amber-800 dark:bg-amber-500/15 dark:text-amber-200" : "bg-slate-100 text-slate-600 dark:bg-white/10 dark:text-slate-300"}`}>{way.status === "active" ? "Đang áp dụng" : way.status === "configured" ? "Theo tiến trình" : "Chờ cấu hình"}</span></div><p className="mt-2 text-sm leading-6 text-slate-500">{way.description}</p><p className="mt-2 text-xs font-bold leading-5 text-amber-800 dark:text-amber-200">Mốc: {way.milestone}</p>{way.view && <button className="secondary-button mt-3 px-3 py-2 text-xs" onClick={() => onView(way.view!)}><CheckCircle2 className="h-3.5 w-3.5" />{way.label}</button>}</div></div></article>)}</div><p className="mt-5 text-xs leading-5 text-slate-500">Mảnh có sáu cấp I–VI và giá trị quy đổi riêng. Chúng được dùng để mở khóa hồ sơ, nâng cấp tư liệu, đổi Vé Sưu Tầm hoặc mua vật phẩm trong Cửa hàng Sưu tầm.</p></section>
    </PersistentCollapsible>
    <PersistentCollapsible storageKey="museum-journey-map" eyebrow="Bản đồ tiến trình" title="Bản đồ Thành tích"><JourneyAchievementMap profile={profile} config={config} /></PersistentCollapsible>
    <PersistentCollapsible storageKey="museum-achievement-museum" eyebrow="Bảo tàng hiện vật" title="Hiện vật đã mở khóa"><AchievementMuseum profile={profile} config={config} /></PersistentCollapsible>
    <PersistentCollapsible storageKey="museum-progress-tree" eyebrow="Cây kỹ năng" title="Cây tiến bộ"><ProgressTree profile={profile} config={config} /></PersistentCollapsible>
    <PersistentCollapsible storageKey="museum-achievement-moments" eyebrow="Lưu dấu hành trình" title="Khoảnh khắc khi đạt"><AchievementMoments profile={profile} config={config} onProfile={onProfile} /></PersistentCollapsible>
    {config.characters.length > 0 && <PersistentCollapsible storageKey="museum-characters" eyebrow="Kho nhân vật lịch sử" title="Mảnh ghép mở khóa hồ sơ"><section className="mt-0" aria-labelledby="fragment-map-title" aria-describedby="fragment-map-status">
      <div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">KHO NHÂN VẬT LỊCH SỬ</p><h2 id="fragment-map-title" className="mt-2 font-display text-2xl font-bold">Mảnh ghép mở khóa hồ sơ, không ghép tranh</h2><p id="fragment-map-status" role="status" aria-live="polite" className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Mỗi mảnh là một phần giá trị để mở khóa và hoàn thiện hồ sơ nhân vật lịch sử. Khi đủ ngưỡng, Ong mở được tiểu sử, dòng thời gian và tư liệu có nguồn xác minh.</p></div><span className="inline-flex items-center gap-2 rounded-full bg-amber-100 px-3 py-2 text-sm font-bold text-amber-900 dark:bg-amber-500/15 dark:text-amber-100"><Puzzle className="h-4 w-4" />{Object.values(profile.fragments).reduce((sum, value) => sum + Math.max(0, value), 0)} mảnh đang giữ</span></div>
      <div className="mt-6 grid gap-3 md:grid-cols-3"><div className="rounded-2xl border border-amber-200 bg-amber-50/70 p-4 dark:border-amber-400/15 dark:bg-amber-500/[.06]"><p className="text-xs font-bold uppercase tracking-wide text-amber-700 dark:text-amber-300">Giá trị bộ sưu tập</p><p className="mt-1 text-2xl font-black text-amber-900 dark:text-amber-100">{totalCollectionValue(config, profile)} điểm mảnh</p><p className="mt-1 text-xs text-slate-500">Tính theo cấp I–VI từ cấu hình.</p></div><div className="rounded-2xl border border-green-200 bg-green-50/70 p-4 dark:border-green-400/15 dark:bg-green-500/[.06]"><p className="text-xs font-bold uppercase tracking-wide text-green-700 dark:text-green-300">Vé Sưu Tầm</p><p className="mt-1 text-2xl font-black text-green-900 dark:text-green-100">{collectionTicketQuote(config, totalCollectionValue(config, profile)).tickets} vé</p><p className="mt-1 text-xs text-slate-500">Tỷ lệ do Admin cấu hình.</p></div><div className="rounded-2xl border border-red-200 bg-red-50/70 p-4 dark:border-red-400/15 dark:bg-red-500/[.06]"><p className="text-xs font-bold uppercase tracking-wide text-red-700 dark:text-red-300">Giá trị cấp mảnh</p><div className="mt-2 flex flex-wrap gap-1.5">{(["I", "II", "III", "IV", "V", "VI"] as FragmentTier[]).map((tier) => <span key={tier} className="rounded-full bg-white/80 px-2 py-1 text-[11px] font-bold text-red-800 dark:bg-white/10 dark:text-red-200">{tier}: {configuredFragmentValue(config, tier)}</span>)}</div></div></div>
      <div className="mt-6 grid gap-4 lg:grid-cols-2">{config.characters.map((character) => {
        const progress = getCharacterProgress(profile, character);
        const held = Math.min(character.fragmentTotal, progress.collectedPieceIds.length || Math.max(0, profile.fragments[character.id] ?? 0));
        const unlocked = progress.status === "unlocked";
        const ready = progress.status === "ready";
        const stage = unlocked ? "complete" : held > 0 ? "assembling" : "collecting";
        const stageLabel = unlocked ? "Giai đoạn 5 · Đọc lịch sử" : ready ? "Giai đoạn 4 · Sẵn sàng ghép" : held > 0 ? "Giai đoạn 2 · Đang ghép" : "Giai đoạn 1 · Thu thập";
        const tiles = Array.from({ length: character.fragmentTotal }, (_, index) => index);
        const imageStatus = character.imageStatus ?? (character.imageUrl ? "available" : "missing");
        const imageLabel = imageStatus === "available" && character.imageUrl ? "Ảnh nhân vật đã được Admin cung cấp" : imageStatus === "updating" ? "Ảnh đang được cập nhật" : "Chưa có ảnh — Admin chưa tải ảnh lên";
        const rarityLabel = character.rarity ?? "chưa phân loại";
        const unlockCost = character.unlockCost ?? character.fragmentCost ?? character.fragmentTotal;
        return <article className={`rounded-3xl border border-amber-100 bg-amber-50/50 p-4 dark:border-amber-400/15 dark:bg-amber-500/[.04] fragment-assembly fragment-assembly--${stage} ${unlocked ? "achievement-card--unlocked" : ""}`} key={character.id}><div className="mb-4 grid gap-3 sm:grid-cols-[104px_1fr] sm:items-start"><div className="flex min-h-24 items-center justify-center overflow-hidden rounded-2xl border border-amber-200/80 bg-amber-100/60 text-center text-[11px] font-bold text-amber-800 dark:border-amber-400/15 dark:bg-amber-500/10 dark:text-amber-200">{imageStatus === "available" && character.imageUrl ? <img src={character.imageUrl} alt={`Ảnh ${character.name}`} className="h-24 w-full object-cover" /> : imageStatus === "updating" ? "Ảnh đang cập nhật" : "Chưa có ảnh"}</div><div><p className="text-xs font-bold uppercase tracking-wide text-amber-700 dark:text-amber-300">{imageLabel}</p><p className="mt-1 text-xs text-slate-500">Độ hiếm: {rarityLabel} · Chi phí mở khóa: {unlockCost} điểm mảnh</p><p className="mt-1 text-xs leading-5 text-slate-600 dark:text-slate-300">Mảnh dùng để mở khóa và nâng cấp hồ sơ hình ảnh nhân vật lịch sử; không dùng để ghép tranh.</p></div></div><div className="flex items-start justify-between gap-4"><div><h3 className="font-display text-lg font-bold">{character.name}</h3><p className="mt-1 text-sm text-slate-500">{stageLabel} · {unlocked ? "Đã mở khóa — xem chi tiết trong Bảo tàng." : `Đang sở hữu ${held}/${character.fragmentTotal} mảnh hồ sơ · còn ${character.fragmentTotal - held} mảnh để mở khóa.`}</p>{character.sourceName && character.sourceUrl ? <a className="mt-2 inline-block text-xs font-bold text-amber-800 underline dark:text-amber-200" href={character.sourceUrl} target="_blank" rel="noreferrer">Nguồn: {character.sourceName}</a> : <p role="status" className="mt-2 text-xs font-bold text-orange-700 dark:text-orange-300">Cảnh báo: nội dung này chưa có nguồn xác minh.</p>}{(character.period || character.historicalPeriod || character.category || character.field) && <p className="mt-1 text-xs text-slate-500">{character.historicalPeriod ?? character.period ?? ""}{character.category ?? character.field ? ` · ${character.category ?? character.field}` : ""}</p>}{character.sourceName && character.sourceUrl ? <a className="mt-2 inline-block text-xs font-bold text-amber-800 underline dark:text-amber-200" href={character.sourceUrl} target="_blank" rel="noreferrer">Nguồn: {character.sourceName}</a> : <p role="status" className="mt-2 text-xs font-bold text-orange-700 dark:text-orange-300">Cảnh báo: nội dung này chưa có nguồn xác minh.</p>}</div>{!unlocked && <LockKeyhole className="h-5 w-5 shrink-0 text-amber-700 dark:text-amber-300" aria-label="Nhân vật chưa mở khóa" />}</div><div className="mt-4 grid grid-cols-6 gap-1.5" role="img" aria-label={`${character.name}: ${held} trên ${character.fragmentTotal} mảnh hồ sơ đã thu thập`}>{tiles.map((tile) => <span key={tile} className={`fragment-tile ${tile < held ? "fragment-tile--held" : "fragment-tile--missing"}`} aria-hidden="true" />)}</div>{unlocked && character.profileLevels && character.profileLevels.length > 0 && <div className="mt-4 rounded-2xl border border-amber-200/80 bg-white/60 p-3 dark:border-amber-400/15 dark:bg-white/[.035]"><p className="text-xs font-bold uppercase tracking-wide text-amber-700 dark:text-amber-300">Nâng cấp hồ sơ</p><div className="mt-2 grid gap-2">{character.profileLevels.map((level) => { const levelUnlocked = (progress.unlockedProfileLevelIds ?? []).includes(level.id); return <div key={level.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-slate-200/70 p-2 dark:border-white/10"><div><p className="text-sm font-bold">{levelUnlocked ? "🔓" : "🔒"} {level.label}</p><p className="text-xs text-slate-500">{level.description} · cần {level.requiredValue} điểm mảnh</p></div>{!levelUnlocked && <button className="secondary-button px-2.5 py-1.5 text-xs" onClick={() => { const result = unlockCharacterProfileLevel(config, profile, character, level.id); if (result.unlocked) onProfile(result.profile, `Đã mở ${level.label} của ${character.name}.`); }}>Mở bằng mảnh</button>}</div>; })}</div></div>}<div className="mt-3 flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-bold text-amber-800 dark:text-amber-200">{held}/{character.fragmentTotal} mảnh ghép · {progress.status === "unlocked" ? "Đã dùng mở khóa hồ sơ" : "Đang sở hữu"}</p>{ready && <button className="primary-button px-3 py-2 text-xs" onClick={() => { const result = assembleCharacter(profile, character); if (result.assembled) onProfile(result.profile, `Đã dùng mảnh để mở khóa hồ sơ ${character.name}.`); }}><Puzzle className="h-3.5 w-3.5" />Mở khóa hồ sơ</button>}{unlocked && <button className="secondary-button px-3 py-2 text-xs" onClick={() => onView("history")}><BookOpen className="h-3.5 w-3.5" />Đọc lịch sử</button>}</div></article>;
      })}</div>
    </section></PersistentCollapsible>}
    {config.collectionConfig && <PersistentCollapsible storageKey="museum-collection-shop" eyebrow="Cửa hàng sưu tầm" title="Cửa hàng đổi mảnh"><section className="panel mt-7 p-6" aria-labelledby="collection-shop-title"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-green-700 dark:text-green-300">CỬA HÀNG SƯU TẦM</p><h2 id="collection-shop-title" className="mt-2 font-display text-2xl font-bold">Đổi giá trị mảnh thành vật phẩm học tập</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Vật phẩm có giá, loại tiền, độ hiếm và trạng thái rõ ràng. Mảnh cấp cao có giá trị lớn hơn nhưng vẫn được tiêu theo ledger, không tạo lợi thế vô hạn.</p></div><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-amber-100 px-3 py-2 text-sm font-bold text-amber-900 dark:bg-amber-500/15 dark:text-amber-100">{collectionValueBalance(config, profile)} điểm mảnh khả dụng</span>{config.collectionConfig.ticketExchange.enabled && <button className="secondary-button px-3 py-2 text-xs" disabled={collectionValueBalance(config, profile) < config.collectionConfig.ticketExchange.fragmentValue} onClick={() => { const result = exchangeCollectionTickets(config, profile, config.collectionConfig!.ticketExchange.fragmentValue); if (result.exchanged) onProfile(result.profile, `Đã đổi ${result.tickets} Vé Sưu Tầm.`); }}>Đổi 1 gói vé</button>}</div></div><div className="mt-6 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{config.collectionConfig.shopItems.filter((item) => item.enabled && !item.deletedAt && !item.cosmeticType).map((item) => { const owned = (profile.collectionInventory ?? []).includes(item.id); const canBuy = item.currency === "collectionTicket" ? (profile.collectionTickets ?? 0) >= item.price : collectionValueBalance(config, profile) >= item.price; return <article key={item.id} className="rounded-2xl border border-green-200/80 bg-green-50/50 p-4 dark:border-green-400/15 dark:bg-green-500/[.04]"><div className="flex items-start justify-between gap-3"><div><h3 className="font-display text-base font-bold">{item.name}</h3><p className="mt-1 text-sm text-slate-500">{item.description}</p></div><span className="rounded-full bg-white/80 px-2 py-1 text-[10px] font-bold uppercase text-green-800 dark:bg-white/10 dark:text-green-200">{item.rarity}</span></div><div className="mt-4 flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-bold text-green-800 dark:text-green-200">{item.price} {item.currency === "collectionTicket" ? "Vé Sưu Tầm" : "điểm mảnh"} · {item.stock === null ? "Không giới hạn" : `còn ${item.stock}`}</p><button className="primary-button px-3 py-2 text-xs" disabled={owned || !canBuy || (item.stock !== null && item.stock <= 0)} onClick={() => { const result = purchaseCollectionItem(config, profile, item); if (result.purchased) onProfile(result.profile, `Đã nhận vật phẩm ${item.name}.`); }}>{owned ? "Đã sở hữu" : "Đổi vật phẩm"}</button></div></article>; })}</div></section></PersistentCollapsible>}
    {config.collectionConfig && <>
      <PersistentCollapsible storageKey="museum-fragment-vault" eyebrow="Kho mảnh ghép" title="Kho mảnh ghép"><section className="panel mt-7 p-6" aria-labelledby="fragment-vault-title"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-red-700 dark:text-red-300">KHO MẢNH GHÉP</p><h2 id="fragment-vault-title" className="mt-2 font-display text-2xl font-bold">Số dư và lịch sử luôn minh bạch</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Mọi mảnh nhận, dùng hoặc quy đổi đều được ghi lại. Hệ thống kiểm tra số dư trước giao dịch và không cho phép phát sinh mảnh âm.</p></div><div className="rounded-2xl bg-red-50 px-4 py-3 text-right dark:bg-red-500/10"><p className="text-xs font-bold uppercase text-red-700 dark:text-red-300">Tổng giá trị</p><p className="mt-1 text-2xl font-black text-red-800 dark:text-red-100">{collectionValueBalance(config, profile)} điểm</p></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{(["I", "II", "III", "IV", "V", "VI"] as const).map((tier) => { const amount = profile.fragmentLedger?.[tier] ?? 0; const tierConfig = config.collectionConfig!.tierValues.find((item) => item.tier === tier); return <div key={tier} className="rounded-2xl border border-red-200/70 bg-white/60 p-4 dark:border-red-400/15 dark:bg-white/[.03]"><div className="flex items-center justify-between"><p className="font-display text-lg font-bold">Cấp {tier}</p><span className="text-xs font-bold text-red-700 dark:text-red-300">×{tierConfig?.value ?? 0} điểm</span></div><p className="mt-2 text-2xl font-black">{amount}</p><p className="text-xs text-slate-500">{tierConfig?.rarity ?? "chưa cấu hình"} · {amount * (tierConfig?.value ?? 0)} điểm</p></div>; })}</div><div className="mt-7 overflow-x-auto rounded-2xl border border-slate-200/80 dark:border-white/10"><table className="w-full min-w-[980px] text-left text-sm"><caption className="border-b border-slate-200/80 px-4 py-3 text-left font-display font-bold dark:border-white/10">Lịch sử mảnh ghép · mọi giao dịch đều có nguồn và lý do</caption><thead className="bg-slate-50/80 text-xs uppercase text-slate-500 dark:bg-white/[.03]"><tr><th className="px-4 py-3">Thời gian</th><th className="px-4 py-3">Nguồn</th><th className="px-4 py-3">Source type / ID</th><th className="px-4 py-3">Lý do</th><th className="px-4 py-3">Loại</th><th className="px-4 py-3">Số lượng</th><th className="px-4 py-3">Cấp</th></tr></thead><tbody>{(profile.pieceTransactions ?? []).slice().sort((a, b) => b.occurredAt.localeCompare(a.occurredAt)).slice(0, 20).map((tx) => <tr key={tx.id} className="border-t border-slate-200/70 dark:border-white/10"><td className="px-4 py-3 whitespace-nowrap">{new Date(tx.occurredAt).toLocaleDateString("vi-VN")}</td><td className="px-4 py-3">{tx.source}{tx.description ? <span className="block text-xs text-slate-500">{tx.description}</span> : null}</td><td className="px-4 py-3 text-xs"><span className="font-bold">{tx.sourceType ?? "legacy"}</span><span className="block text-slate-500">{tx.sourceId ?? tx.relatedId ?? "—"}</span></td><td className="max-w-[220px] px-4 py-3 text-xs text-slate-600 dark:text-slate-300">{tx.reason ?? tx.description ?? "Chưa có lý do"}</td><td className="px-4 py-3">{tx.type === "grant" ? "Nhận" : tx.type === "spend" ? "Dùng" : tx.type === "exchange" ? "Quy đổi" : "Hoàn"}</td><td className={"px-4 py-3 font-bold " + (tx.type === "spend" ? "text-red-700 dark:text-red-300" : "text-green-700 dark:text-green-300")}>{tx.type === "spend" ? "-" : "+"}{tx.amount}</td><td className="px-4 py-3">{tx.tier}</td></tr>)}{(profile.pieceTransactions ?? []).length === 0 && <tr><td colSpan={7} className="px-4 py-8 text-center text-sm text-slate-500">Chưa có giao dịch. Khi nhận hoặc sử dụng mảnh, lịch sử sẽ xuất hiện tại đây.</td></tr>}</tbody></table></div><div className="mt-5 rounded-2xl border border-red-200/70 bg-red-50/40 p-4 dark:border-red-400/15 dark:bg-red-500/[.04]"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-red-700 dark:text-red-300">NHẬT KÝ KIỂM TOÁN</p><p className="mt-1 text-sm text-slate-600 dark:text-slate-300">Mỗi lần nhận, đổi hoặc điều chỉnh phần thưởng đều để lại dấu vết riêng; retry cùng claim key không tạo bản ghi mới.</p></div><span className="rounded-full bg-white/80 px-3 py-1 text-xs font-bold text-red-800 dark:bg-white/10 dark:text-red-200">{(profile.rewardAuditLogs ?? []).length} bản ghi</span></div>{(profile.rewardAuditLogs ?? []).length > 0 && <div className="mt-3 grid gap-2 sm:grid-cols-2">{(profile.rewardAuditLogs ?? []).slice().sort((a, b) => b.occurredAt.localeCompare(a.occurredAt)).slice(0, 4).map((audit) => <div key={audit.id} className="rounded-xl border border-red-200/70 bg-white/70 p-3 text-xs dark:border-red-400/15 dark:bg-white/[.03]"><p className="font-bold">{audit.action} · {audit.entityType}</p><p className="mt-1 text-slate-500">{audit.summary}</p><p className="mt-1 text-slate-400">{new Date(audit.occurredAt).toLocaleString("vi-VN")}</p></div>)}</div>}</div></section></PersistentCollapsible>
      <PersistentCollapsible storageKey="museum-learning-milestones" eyebrow="Mốc học tập" title="Mốc học tập"><section className="panel mt-7 p-6" aria-labelledby="learning-milestones-title"><p className="text-xs font-bold uppercase tracking-[.16em] text-green-700 dark:text-green-300">MỐC HỌC TẬP</p><h2 id="learning-milestones-title" className="mt-2 font-display text-2xl font-bold">Phần thưởng theo tổng thời gian học</h2><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{(config.collectionConfig.learningMilestones ?? []).filter((milestone) => milestone.enabled).map((milestone) => { const studied = profile.studyActivity.reduce((sum, activity) => sum + (activity.durationSeconds ?? 0), 0); const progress = Math.min(100, Math.round((studied / milestone.studySeconds) * 100)); const claimed = Boolean(profile.claimedMilestones?.[milestone.id]); return <article key={milestone.id} className="rounded-2xl border border-green-200/70 bg-green-50/40 p-4 dark:border-green-400/15 dark:bg-green-500/[.04]"><div className="flex items-start justify-between gap-3"><h3 className="font-display font-bold">{milestone.label}</h3><span className="text-xs font-bold text-green-700 dark:text-green-300">{claimed ? "Đã nhận" : `${progress}%`}</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-green-100 dark:bg-green-950"><div className="h-full rounded-full bg-green-600" style={{ width: `${progress}%` }} /></div><p className="mt-2 text-xs text-slate-500">Mục tiêu {Math.ceil(milestone.studySeconds / 3600)} giờ · Phần thưởng: {milestone.rewards.map((reward) => `${reward.amount} mảnh Cấp ${reward.tier}`).join(", ")}</p></article>; })}</div></section></PersistentCollapsible>
      <PersistentCollapsible storageKey="museum-system-guide" eyebrow="Hướng dẫn hệ thống" title="Hệ thống hoạt động thế nào"><section className="panel mt-7 p-6" aria-labelledby="system-guide-title"><p className="text-xs font-bold uppercase tracking-[.16em] text-amber-700 dark:text-amber-300">HỆ THỐNG HOẠT ĐỘNG THẾ NÀO?</p><h2 id="system-guide-title" className="mt-2 font-display text-2xl font-bold">Không có phần thưởng ẩn</h2><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4">{[{ title: "Thành tích & Danh hiệu", text: "Điều kiện, tiến độ và phần thưởng được công khai cho cả mục chưa đạt." }, { title: "Mảnh ghép", text: "Mảnh có cấp, giá trị, nguồn nhận và lịch sử sử dụng rõ ràng." }, { title: "Event", text: "Event có thời gian, nhiệm vụ, điều kiện tham gia, giới hạn và phần thưởng cụ thể." }, { title: "Cửa hàng", text: "Giá, loại tiền, độ hiếm, tồn kho và tỷ lệ quy đổi do Admin cấu hình." }].map((item) => <div key={item.title} className="rounded-2xl border border-amber-200/70 bg-amber-50/40 p-4 dark:border-amber-400/15 dark:bg-amber-500/[.04]"><h3 className="font-display font-bold">{item.title}</h3><p className="mt-2 text-sm leading-6 text-slate-600 dark:text-slate-300">{item.text}</p></div>)}</div></section></PersistentCollapsible>
    </>}
  </>;
}
